package controlsys

import (
	"testing"

	"plantcontrol.org/v1/gonum/mat"
)

// TestCareDescriptorFailedGainRefinementKeepsValue: triangular E with last
// pivot 4.4e-14, cross term S and cheap R (O2MVDD, r2bGen seed 17976). The
// Newton step moves EᵀXE by 2.3e-7 and K by 1.35e-8, and the double-double
// refinement this triggers stalls; EᵀXE does not cancel, so X stays
// certified and K (5.7e-9 off the 320-bit gain) is returned, not
// ErrNoStabilizing, at Accuracy 1 unless within newtonTol.
func TestCareDescriptorFailedGainRefinementKeepsValue(t *testing.T) {
	A := mat.NewDense(6, 6, []float64{0.20867466656127104, -0.6445668288562542, 0.057444479232218244, 0.4612142607920148, 0.03941363521174515, -0.2575870925294462, 0.3240250174414761, 0.20391048685435745, -0.4081608056184013, 0.35126666805289336, -0.7555796283513716, 0.19148410473413108, 0.7914423336219166, 0.17150332587473574, 0.14558856741744933, 0.5909696312696691, 0.10438119999176992, 0.1640027628135815, -0.08179873331695156, 0.011519301933801959, -0.4619795405534733, -0.18759357529947365, 0.06266313765237637, 0.8649934025561685, 0.8845495676998629, -0.36692133690250894, 0.2359157032607299, 0.661522513216132, -0.35523547078593226, -0.3383335018596025, 0.055547497202339896, -0.00765079220711797, 0.47208017211568465, 0.922878831722566, 0.2042288232478939, 0.21726838826398617})
	B := mat.NewDense(6, 3, []float64{0.02631762027293741, -1.4303147277238928, 1.7117714690298538, 2.393526283443206, 0.6882138933314396, -0.019528955134694714, -0.5255609621210268, 0.8309893267052659, -0.25434680719997127, -0.14252942315232187, -0.9615667521238929, 0.5405049896156691, -0.41957491381129974, 1.273299617179417, 1.0847227672223303, -0.22647261329104218, 0.20171139557443984, 0.23167280007809454})
	E := mat.NewDense(6, 6, []float64{-1.2499398604926246, -0.14088503997156984, -0.4310432708739138, 0.8979985817321615, -0.05632045029245614, -0.2980318113150452, 0, 1.3964882653087851, 0.4865716264595368, -0.4483034090174909, 0.8505964322516733, -0.6042383819324642, 0, 0, 1.3627414248627563, 1.0593147883837697, 1.2189370230924144, 0.6462589092272828, 0, 0, 0, 1.1574926990008418, 0.3655894381809188, 0.4748580390310801, 0, 0, 0, 0, -0.612202486306702, 0.43679164846936236, 0, 0, 0, 0, 0, -4.377563014184253e-14})
	Q := mat.NewDense(6, 6, []float64{0.024828915086904445, -0.0049730512820884845, -0.0044194473359073, -0.007724216992385617, -0.01442463210630172, 0.006015425274775725, -0.0049730512820884845, 0.0009960737923970073, 0.0008851834549828793, 0.001547105003108647, 0.002889149867444183, -0.0012048463355710866, -0.0044194473359073, 0.0008851834549828793, 0.0007866515988485728, 0.0013748800678938403, 0.002567527451546987, -0.001070721902083649, -0.007724216992385617, 0.001547105003108647, 0.0013748800678938403, 0.002402993887747633, 0.004487470414801152, -0.0018713851940258643, -0.01442463210630172, 0.002889149867444183, 0.002567527451546987, 0.004487470414801152, 0.008380159112424923, -0.003494728718731407, 0.006015425274775725, -0.0012048463355710866, -0.001070721902083649, -0.0018713851940258643, -0.003494728718731407, 0.001457395021365842})
	R := mat.NewDense(3, 3, []float64{2.537546937221814e-06, -1.586689065040869e-07, -1.484518646343326e-07, -1.586689065040869e-07, 2.537546937221814e-06, -1.0345150618494639e-07, -1.484518646343326e-07, -1.0345150618494639e-07, 2.537546937221814e-06})
	S := mat.NewDense(6, 3, []float64{5.131015479608521e-05, 8.531825996917146e-05, 1.2991747098556098e-05, -1.0277054266284336e-05, -1.7088632671110708e-05, -2.6021533257173093e-06, -9.133004572402262e-06, -1.5186312758255389e-05, -2.3124795886146795e-06, -1.5962473075878917e-05, -2.6542317657218313e-05, -4.041703130569237e-06, -2.9809209380482e-05, -4.956659915579656e-05, -7.547701054853881e-06, 1.243117122204422e-05, 2.0670487201971417e-05, 3.1475764066096553e-06})
	res, err := Care(A, B, Q, R, &RiccatiOpts{E: E, S: S})
	if err != nil {
		t.Fatalf("Care: %v", err)
	}
	_, _, Ko, ok := nearSingularOracle(true, A, B, Q, R, S, E, res.K)
	if !ok {
		t.Fatal("oracle did not converge")
	}
	e := relErr(res.K, Ko)
	t.Logf("Accuracy %d, K off the 320-bit gain by %.3g", res.Accuracy, e)
	if res.Accuracy == 0 && e > newtonTol {
		t.Errorf("Accuracy 0 with K off the 320-bit gain by %.3g", e)
	}
}

// TestDareDescriptorRefinedGainTerminal: row-scaled E (σ_min 8.1e-5;
// O2MVDD, r2bGen seed 3661). The double-double K formed while certifying
// is terminal; replacing it by the gain of the rounded float64 X left K
// 1.9e-6 off the 320-bit gain (K sensitivity 1.5e-10) at Accuracy 0.
func TestDareDescriptorRefinedGainTerminal(t *testing.T) {
	A := mat.NewDense(4, 4, []float64{0.7253996614054934, -0.8165634358638546, -1.1361885752452694, 0.13359044056270253, 0.2236931001986604, -0.1607237329742234, 0.4031449391484957, 0.3844018280254162, 0.22677862581556635, 0.12655525871269957, 0.9437065483052647, -0.9282868215954716, -0.345338252514762, -0.4202788758801942, 0.5207863771460748, 0.9422534694288364})
	B := mat.NewDense(4, 3, []float64{-0.07593149831154966, 0.9728809873704531, -0.7725712579908381, -0.32398928956195794, 1.4991393876331618, -0.872981203294598, -0.73130686852871, 1.136234131002702, 1.1679088973880116, 0.9809870514363661, -0.9655939900713162, -0.38058638071806355})
	E := mat.NewDense(4, 4, []float64{0.1943399561039921, -0.035176668242979284, 0.012331630336251986, 0.030342205893985497, 0.048343930606189515, 2.3699823609973656, 0.37430538040318906, 0.025743328787095038, 1.2194933375043046e-06, 7.105900802532365e-06, 8.416849413364635e-05, 4.974140887400728e-06, -0.15995116259027098, 0.40900576748927536, 0.44793323011894975, 4.314339872465464})
	Q := mat.NewDense(4, 4, []float64{214.20082001970061, 376.50977128254897, -421.7815067847609, 370.36449664565055, 376.50977128254897, 707.8938920542845, -770.1364328431752, 697.5739361810246, -421.7815067847609, -770.1364328431752, 848.4667975668389, -758.3365319383207, 370.36449664565055, 697.5739361810246, -758.3365319383207, 687.4356534223199})
	R := mat.NewDense(3, 3, []float64{0.00025329922570458665, 2.710529214626445e-08, -9.819291409187042e-06, 2.710529214626445e-08, 0.00025329922570458665, -3.028601370327947e-06, -9.819291409187042e-06, -3.028601370327947e-06, 0.00025329922570458665})
	for _, tc := range []struct {
		name  string
		solve func(a, b, q, r *mat.Dense, o *RiccatiOpts) (*RiccatiResult, error)
	}{{"Dare", Dare}, {"Dlqr", Dlqr}} {
		res, err := tc.solve(A, B, Q, R, &RiccatiOpts{E: E})
		if err != nil {
			t.Fatalf("%s: %v", tc.name, err)
		}
		_, _, Ko, ok := nearSingularOracle(false, A, B, Q, R, nil, E, res.K)
		if !ok {
			t.Fatalf("%s: oracle did not converge", tc.name)
		}
		e := relErr(res.K, Ko)
		t.Logf("%s: Accuracy %d, K off the 320-bit gain by %.3g", tc.name, res.Accuracy, e)
		if res.Accuracy == 0 && e > newtonTol {
			t.Errorf("%s: Accuracy 0 with K off the 320-bit gain by %.3g", tc.name, e)
		}
	}
}
